import { useState, useRef, useCallback } from 'react';

export function useChat() {
  const [messages, setMessages] = useState([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const accRef = useRef('');

  const sendMessage = useCallback(async (userContent) => {
    const userMsg = { id: crypto.randomUUID(), role: 'user', content: userContent, status: 'done' };
    const assistantId = crypto.randomUUID();
    const assistantMsg = { id: assistantId, role: 'assistant', content: '', status: 'streaming' };

    setMessages(prev => [...prev, userMsg, assistantMsg]);
    setIsStreaming(true);
    accRef.current = '';

    const allMessages = [...messages, userMsg].map(({ role, content }) => ({ role, content }));

    const res = await fetch('/api/chat/stream', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ messages: allMessages }),
    });

    const reader = res.body.getReader();
    const decoder = new TextDecoder();

    const flush = setInterval(() => {
      const snapshot = accRef.current;
      setMessages(prev => prev.map(m =>
        m.id === assistantId ? { ...m, content: snapshot } : m
      ));
    }, 50);

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      const text = decoder.decode(value);
      for (const line of text.split('\n')) {
        if (!line.startsWith('data: ')) continue;
        const payload = line.slice(6);
        if (payload === '[DONE]') break;
        try {
          const { delta } = JSON.parse(payload);
          if (delta) accRef.current += delta;
        } catch {}
      }
    }

    clearInterval(flush);
    setMessages(prev => prev.map(m =>
      m.id === assistantId ? { ...m, content: accRef.current, status: 'done' } : m
    ));
    setIsStreaming(false);
  }, [messages]);

  return { messages, sendMessage, isStreaming };
}

import OpenAI from 'openai';
import { encode } from 'gpt-tokenizer';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

const MAX_HISTORY_TOKENS = 6000;
const SUMMARY_MODEL = 'gpt-4o-mini';
const CHAT_MODEL = 'gpt-4o';

function countTokens(messages) {
  return messages.reduce((acc, m) => acc + encode(m.content).length + 4, 0);
}

async function summariseHistory(messages) {
  const transcript = messages
    .map(m => `${m.role.toUpperCase()}: ${m.content}`)
    .join('\n');

  const res = await openai.chat.completions.create({
    model: SUMMARY_MODEL,
    messages: [
      {
        role: 'system',
        content: 'Summarise the key facts, decisions, and user preferences from this conversation in concise bullet points.',
      },
      { role: 'user', content: transcript },
    ],
    max_tokens: 400,
  });

  return res.choices[0].message.content;
}

export async function buildContextMessages(systemPrompt, history, newUserMessage) {
  let workingHistory = [...history];

  if (countTokens(workingHistory) > MAX_HISTORY_TOKENS) {
    const summary = await summariseHistory(workingHistory);
    workingHistory = [
      { role: 'system', content: `Previous conversation summary:\n${summary}` },
    ];
  }

  return [
    { role: 'system', content: systemPrompt },
    ...workingHistory,
    { role: 'user', content: newUserMessage },
  ];
}

