const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
const client = new MongoClient(process.env.MONGODB_URI);
const db = client.db('ragdb');
const chunks = db.collection('doc_chunks');

function splitIntoChunks(text, chunkSize = 500, overlap = 50) {
  const words = text.split(/\s+/);
  const result = [];
  let start = 0;
  while (start < words.length) {
    const end = Math.min(start + chunkSize, words.length);
    result.push({ text: words.slice(start, end).join(' '), index: result.length });
    start += chunkSize - overlap;
  }
  return result;
}

async function embedTexts(texts) {
  const res = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: texts,
  });
  return res.data.map(d => d.embedding);
}

export async function ingestDocument(docId, title, fullText) {
  const chunkList = splitIntoChunks(fullText);
  const texts = chunkList.map(c => c.text);

  // Batch embed in groups of 100 to stay under API limits
  const allEmbeddings = [];
  for (let i = 0; i < texts.length; i += 100) {
    const batch = texts.slice(i, i + 100);
    const embeddings = await embedTexts(batch);
    allEmbeddings.push(...embeddings);
  }

  const docs = chunkList.map((chunk, i) => ({
    docId,
    title,
    chunkIndex: chunk.index,
    text: chunk.text,
    embedding: allEmbeddings[i],
    createdAt: new Date(),
  }));

  await chunks.insertMany(docs);
  console.log(`Ingested ${docs.length} chunks for doc: ${title}`);
}

