function cosineSimilarity(a, b) {
  const dot = a.reduce((sum, val, i) => sum + val * b[i], 0);
  const magA = Math.sqrt(a.reduce((sum, val) => sum + val * val, 0));
  const magB = Math.sqrt(b.reduce((sum, val) => sum + val * val, 0));
  return dot / (magA * magB);
}

async function retrieveTopChunks(query, docId, topK = 5) {
  const embRes = await openai.embeddings.create({
    model: 'text-embedding-3-small',
    input: [query],
  });
  const queryVec = embRes.data[0].embedding;

  const allChunks = await chunks.find({ docId }).toArray();
  return allChunks
    .map(c => ({ ...c, score: cosineSimilarity(queryVec, c.embedding) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, topK);
}

export async function answerWithRAG(userQuery, docId) {
  const topChunks = await retrieveTopChunks(userQuery, docId);
  const context = topChunks.map((c, i) => `[${i + 1}] ${c.text}`).join('\n\n');

  const res = await openai.chat.completions.create({
    model: 'gpt-4o',
    messages: [
      {
        role: 'system',
        content: `You are a helpful assistant. Answer the user's question using ONLY the context below. If the answer is not in the context, say so.\n\nContext:\n${context}`,
      },
      { role: 'user', content: userQuery },
    ],
    max_tokens: 600,
  });

  return {
    answer: res.choices[0].message.content,
    sources: topChunks.map(c => ({ chunkIndex: c.chunkIndex, score: c.score.toFixed(3), preview: c.text.slice(0, 120) })),
  };
}

import OpenAI from 'openai';
import { z } from 'zod';

const openai = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

const ArticleMetaSchema = z.object({
  title: z.string(),
  summary: z.string().max(200),
  tags: z.array(z.string()).max(5),
  sentiment: z.enum(['positive', 'negative', 'neutral']),
  readingTimeMinutes: z.number().int().positive(),
  language: z.enum(['en', 'si', 'mixed']),
});

export async function extractArticleMeta(articleText) {
  const res = await openai.chat.completions.create({
    model: 'gpt-4o',
    response_format: { type: 'json_object' },
    temperature: 0,
    messages: [
      {
        role: 'system',
        content: `You are a metadata extraction assistant. Return a JSON object with EXACTLY these keys:
- title: string (infer or extract from text)
- summary: string (max 200 chars)
- tags: string[] (max 5 relevant tags)
- sentiment: "positive" | "negative" | "neutral"
- readingTimeMinutes: integer (estimate at 200 wpm)
- language: "en" | "si" | "mixed"`,
      },
      { role: 'user', content: `Extract metadata from this article:\n\n${articleText}` },
    ],
  });

  const raw = JSON.parse(res.choices[0].message.content);
  const parsed = ArticleMetaSchema.safeParse(raw);

  if (!parsed.success) {
    throw new Error(`Schema validation failed: ${parsed.error.message}`);
  }

  return parsed.data;
}

