export async function runSupportAgent(messages, customerId) {
  const contextMessages = [
    { role: 'system', content: `You are a helpful customer support agent. The current customer's ID is ${customerId}. Use the provided tools to look up real data. Always be polite and concise.` },
    ...messages,
  ];

  let response = await openai.chat.completions.create({
    model: 'gpt-4o',
    messages: contextMessages,
    tools,
    tool_choice: 'auto',
  });

  // Agentic loop — keep calling until no more tool calls
  while (response.choices[0].finish_reason === 'tool_calls') {
    const toolCalls = response.choices[0].message.tool_calls;
    contextMessages.push(response.choices[0].message);

    for (const call of toolCalls) {
      const args = JSON.parse(call.function.arguments);
      const result = await toolFunctions[call.function.name](args);
      contextMessages.push({
        role: 'tool',
        tool_call_id: call.id,
        content: JSON.stringify(result),
      });
    }

    response = await openai.chat.completions.create({
      model: 'gpt-4o',
      messages: contextMessages,
      tools,
      tool_choice: 'auto',
    });
  }

  return response.choices[0].message.content;
}

