// Simple in-memory circuit breaker
class CircuitBreaker {
  constructor({ threshold = 3, cooldownMs = 60_000 } = {}) {
    this.failures = 0;
    this.threshold = threshold;
    this.cooldownMs = cooldownMs;
    this.state = 'closed'; // closed | open | half-open
    this.nextAttempt = null;
  }

  async call(fn) {
    if (this.state === 'open') {
      if (Date.now() < this.nextAttempt) {
        throw new Error('AI service temporarily unavailable. Please try again shortly.');
      }
      this.state = 'half-open';
    }

    try {
      const result = await fn();
      this.reset();
      return result;
    } catch (err) {
      this.recordFailure();
      throw err;
    }
  }

  recordFailure() {
    this.failures++;
    if (this.failures >= this.threshold) {
      this.state = 'open';
      this.nextAttempt = Date.now() + this.cooldownMs;
      console.error(`Circuit breaker OPEN — AI calls paused for ${this.cooldownMs / 1000}s`);
    }
  }

  reset() {
    this.failures = 0;
    this.state = 'closed';
    this.nextAttempt = null;
  }
}

export const aiCircuitBreaker = new CircuitBreaker({ threshold: 3, cooldownMs: 60_000 });

